--
-- Name: tickets; Type: TABLE; Schema: public; Owner: itdevel
--

CREATE TABLE public.tickets (
    id bigint NOT NULL,
    ticket_number character varying(255) NOT NULL,
    user_id bigint NOT NULL,
    category_id bigint NOT NULL,
    category character varying(255),
    department_id bigint NOT NULL,
    department character varying(255),
    building_id bigint,
    building character varying(255),
    location_id bigint,
    location character varying(255),
    description text NOT NULL,
    priority character varying(255) DEFAULT 'low'::character varying NOT NULL,
    status character varying(255) DEFAULT 'open'::character varying NOT NULL,
    admin_notes text,
    opened_at timestamp(0) without time zone,
    in_progress_at timestamp(0) without time zone,
    closed_at timestamp(0) without time zone,
    confirmed_at timestamp(0) without time zone,
    rejection_notes text,
    rejection_photo character varying(255),
    last_rejection_at timestamp(0) without time zone,
    rejection_count integer DEFAULT 0 NOT NULL,
    confirmation_notes text,
    confirmation_photo character varying(255),
    user_confirmation boolean DEFAULT false NOT NULL,
    user_confirmed_at timestamp(0) without time zone,
    user_confirmation_notes text,
    photo character varying(255),
    user_replies json,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    admin_responses json,
    CONSTRAINT tickets_priority_check CHECK (((priority)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying])::text[]))),
    CONSTRAINT tickets_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'open'::character varying, 'in_progress'::character varying, 'closed'::character varying, 'confirmed'::character varying])::text[])))
);


ALTER TABLE public.tickets OWNER TO itdevel;

